sys_script_include.script:
// AIROPSettingsAjax - handles module settings loads and saves
// Scoped Script Include in x_snc_airop

var AIROPSettingsAjax = Class.create();
AIROPSettingsAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getModuleSettings: function() {
        var modules = ['AIOPS', 'CMDB', 'CREATOR', 'CSM', 'DEX', 'FIELD_SERVICE', 'GRC', 'HAM', 'HRSD', 'ITOM', 'ITSM', 'LSD', 'OTSM', 'PLATFORM', 'SECOPS', 'SAM', 'SPM', 'SPO', 'TPRM', 'VA', 'WSD'];
        var settings = {};

        modules.forEach(function(module) {
            var propName = 'x_snc_airop.module.' + module + '.enabled';
            var value = gs.getProperty(propName, 'false');
            settings[module] = (value === 'true');
        });

        return JSON.stringify(settings);
    },

    saveModuleSettings: function() {
        var modules = ['AIOPS', 'CMDB', 'CREATOR', 'CSM', 'DEX', 'FIELD_SERVICE', 'GRC', 'HAM', 'HRSD', 'ITOM', 'ITSM', 'LSD', 'OTSM', 'PLATFORM', 'SECOPS', 'SAM', 'SPM', 'SPO', 'TPRM', 'VA', 'WSD'];
        var result = {
            success: true,
            error: null,
            saved: []
        };

        try {
            modules.forEach(function(module) {
                var propName = 'x_snc_airop.module.' + module + '.enabled';
                var value = this.getParameter(module);
                var enabled = (value === 'true' || value === true);
                gs.setProperty(propName, enabled ? 'true' : 'false');
                result.saved.push(module + '=' + (enabled ? 'true' : 'false'));
            }, this);
        } catch (e) {
            result.success = false;
            result.error = e.message;
        }

        return JSON.stringify(result);
    },

    type: 'AIROPSettingsAjax'
});
